import React, {useState} from 'react'

export default function TextForm(props) {
    
    const handleupClick = ()=>{
        console.log("Uppercase was Clicked! " + text)
        let newtext = text.toUpperCase();
        setText(newtext);
        //a = "next text updated"; did not change the text in text area
    }

    const handleonChange =(event)=>{
        console.log("On Change");
        setText(event.target.value);
    }

    const [text, setText] = useState('Enter Text Here..');
    //text = "New Text"       wrong way to change the state value
    //setText("New Text");    correct way to change the value of state value

  return (
    <div>
        <h1>{props.heading}</h1>
      <div className='mb-3'>
    <textarea className="form-control" value={text} /*{a}*/ onChange={handleonChange} id="mybox" rows="3"></textarea>
     </div>
     <button className="btn btn-primary" onClick={handleupClick}>Convert to UpperCase</button>
    </div>
  )
}
